import fs from "node:fs";
import path from "node:path";

const PLUGIN_NAME = "vite-plugin-sveltekit-legacy";
const WRAPPER_MARKER = `Generated by ${PLUGIN_NAME}`;
const RUNTIME_POLYFILL_FILE = "legacy-polyfills.js";

type ManifestChunk = {
	file: string;
	name?: string;
	src?: string;
	isEntry?: boolean;
};

type Manifest = Record<string, ManifestChunk>;

export type RewriteOptions = {
	clientOutDir: string;
	failOnMissingPolyfills?: boolean;
};

export type RewriteResult = {
	polyfillFile: string | null;
	runtimePolyfillFile: string | null;
	wrappedFiles: string[];
};

export function rewriteSvelteKitClientEntries(
	options: RewriteOptions,
): RewriteResult {
	const manifestPath = path.join(
		options.clientOutDir,
		".vite",
		"manifest.json",
	);

	if (!fs.existsSync(manifestPath)) {
		if (options.failOnMissingPolyfills === false)
			return {
				polyfillFile: null,
				runtimePolyfillFile: null,
				wrappedFiles: [],
			};
		throw new Error(
			`[${PLUGIN_NAME}] Could not find SvelteKit client manifest at ${manifestPath}.`,
		);
	}

	const manifest = JSON.parse(
		fs.readFileSync(manifestPath, "utf8"),
	) as Manifest;
	const polyfills = manifest["vite/legacy-polyfills"];

	if (!polyfills) {
		if (options.failOnMissingPolyfills === false)
			return {
				polyfillFile: null,
				runtimePolyfillFile: null,
				wrappedFiles: [],
			};
		throw new Error(
			`[${PLUGIN_NAME}] @vitejs/plugin-legacy did not emit vite/legacy-polyfills. Set failOnMissingPolyfills: false to ignore this build shape.`,
		);
	}

	if (polyfills.file.includes("-legacy.")) {
		throw new Error(
			`[${PLUGIN_NAME}] ${polyfills.file} is a legacy polyfill chunk. Full legacy nomodule output is not supported.`,
		);
	}

	copyRuntimePolyfills({
		clientOutDir: options.clientOutDir,
		polyfillFile: polyfills.file,
		runtimePolyfillFile: RUNTIME_POLYFILL_FILE,
	});

	const entryFiles = findSvelteKitEntryFiles(manifest);
	const wrappedFiles = entryFiles.map((entryFile) =>
		wrapEntryFile({
			clientOutDir: options.clientOutDir,
			entryFile,
			polyfillFile: RUNTIME_POLYFILL_FILE,
		}),
	);

	return {
		polyfillFile: polyfills.file,
		runtimePolyfillFile: RUNTIME_POLYFILL_FILE,
		wrappedFiles,
	};
}

function copyRuntimePolyfills(options: {
	clientOutDir: string;
	polyfillFile: string;
	runtimePolyfillFile: string;
}) {
	const sourcePath = path.join(options.clientOutDir, options.polyfillFile);
	const runtimePath = path.join(
		options.clientOutDir,
		options.runtimePolyfillFile,
	);

	if (!fs.existsSync(sourcePath)) {
		throw new Error(
			`[${PLUGIN_NAME}] Expected polyfill file ${sourcePath} does not exist.`,
		);
	}

	if (
		fs.existsSync(runtimePath) &&
		fs.readFileSync(runtimePath, "utf8") === fs.readFileSync(sourcePath, "utf8")
	) {
		return;
	}

	fs.mkdirSync(path.dirname(runtimePath), { recursive: true });
	fs.copyFileSync(sourcePath, runtimePath);
}

function findSvelteKitEntryFiles(manifest: Manifest) {
	const start = findManifestFile(
		manifest,
		(key, chunk) => chunk.name === "entry/start" || key.includes("/entry.js"),
	);
	const app = findManifestFile(
		manifest,
		(key, chunk) =>
			chunk.name === "entry/app" ||
			key.includes("generated/client-optimized/app"),
	);

	const entries = app ? [start, app] : [start];

	if (!start) {
		throw new Error(
			`[${PLUGIN_NAME}] Could not find SvelteKit entry/start in the client manifest.`,
		);
	}

	return entries.filter((entry): entry is string => Boolean(entry));
}

function findManifestFile(
	manifest: Manifest,
	predicate: (key: string, chunk: ManifestChunk) => boolean,
): string | undefined {
	for (const [key, chunk] of Object.entries(manifest)) {
		if (chunk.file && predicate(key, chunk)) return chunk.file;
	}

	return undefined;
}

function wrapEntryFile(options: {
	clientOutDir: string;
	entryFile: string;
	polyfillFile: string;
}) {
	const entryPath = path.join(options.clientOutDir, options.entryFile);
	const originalEntryFile = originalFileName(options.entryFile);
	const originalEntryPath = path.join(options.clientOutDir, originalEntryFile);

	if (!fs.existsSync(entryPath)) {
		throw new Error(
			`[${PLUGIN_NAME}] Expected entry file ${entryPath} does not exist.`,
		);
	}

	const current = fs.readFileSync(entryPath, "utf8");
	if (current.includes(WRAPPER_MARKER) && fs.existsSync(originalEntryPath)) {
		return options.entryFile;
	}

	if (fs.existsSync(originalEntryPath)) {
		throw new Error(
			`[${PLUGIN_NAME}] Refusing to overwrite existing original entry ${originalEntryPath}.`,
		);
	}

	fs.renameSync(entryPath, originalEntryPath);
	renameSourceMapIfPresent(entryPath, originalEntryPath);
	updateSourceMapCommentIfPresent(originalEntryPath);

	const wrapper = createWrapperModule({
		entryFile: options.entryFile,
		originalEntryFile,
		polyfillFile: options.polyfillFile,
	});

	fs.writeFileSync(entryPath, wrapper);

	return options.entryFile;
}

function originalFileName(file: string) {
	const extension = path.posix.extname(file);
	const withoutExtension = file.slice(0, -extension.length);

	return `${withoutExtension}.sveltekit-original${extension}`;
}

function createWrapperModule(options: {
	entryFile: string;
	originalEntryFile: string;
	polyfillFile: string;
}) {
	const entryDirectory = path.posix.dirname(options.entryFile);
	const polyfillImport = toRelativeImport(entryDirectory, options.polyfillFile);
	const originalImport = toRelativeImport(
		entryDirectory,
		options.originalEntryFile,
	);

	return `// ${WRAPPER_MARKER}
import ${JSON.stringify(polyfillImport)};
export * from ${JSON.stringify(originalImport)};
`;
}

function toRelativeImport(fromDirectory: string, toFile: string) {
	const relative = path.posix.relative(fromDirectory, toFile);

	return relative.startsWith(".") ? relative : `./${relative}`;
}

function renameSourceMapIfPresent(
	entryPath: string,
	originalEntryPath: string,
) {
	const mapPath = `${entryPath}.map`;

	if (!fs.existsSync(mapPath)) return;

	fs.renameSync(mapPath, `${originalEntryPath}.map`);
}

function updateSourceMapCommentIfPresent(originalEntryPath: string) {
	const contents = fs.readFileSync(originalEntryPath, "utf8");
	const sourceMapComment = /\/\/# sourceMappingURL=([^\r\n]+)/;

	if (!sourceMapComment.test(contents)) return;

	fs.writeFileSync(
		originalEntryPath,
		contents.replace(
			sourceMapComment,
			`//# sourceMappingURL=${path.basename(originalEntryPath)}.map`,
		),
	);
}
